async ({ workspace: { read, edit } }) => {
  const out = [];
  for (const f of ["src/workspace/view-image.ts", "src/durable/images.ts"]) {
    const r = await read(f, { format: "raw" });
    const content = JSON.parse(r.content) as string;
    const h = await read(f, { limit: 1 });
    out.push(await edit(f, { revision: h.revision, changes: [{ kind: "replaceFile", content }] }));
  }
  return out;
}
